import os, sys
sys.path.insert(0, os.path.join(os.getcwd(), 'src'))
import attrs, attr

@attrs.define
class Plain:
    x: int = 1

assert '__setattr__' not in Plain.__dict__
assert attrs.inspect(Plain).on_setattr_hook is not None

@attrs.define(on_setattr=attr.setters.pipe(attr.setters.convert, attr.setters.validate))
class Manual:
    x: int = 1

assert '__setattr__' in Manual.__dict__
print('ok')

import os, sys
sys.path.insert(0, os.path.join(os.getcwd(), 'src'))
import attrs

try:
    @attrs.define(cache_hash=True)
    class Bad:
        x: int = 1
    raise AssertionError('should have raised')
except TypeError as e:
    assert 'cache_hash' in str(e)

@attrs.frozen(cache_hash=True)
class Good:
    x: int = 1

g = Good(1)
assert hash(g) == hash(g)
assert '_attrs_cached_hash' in Good.__slots__
print('ok')

import os, sys
sys.path.insert(0, os.path.join(os.getcwd(), 'src'))
import attrs

try:
    @attrs.define(frozen=True, on_setattr=attrs.setters.validate)
    class F:
        x: int = attrs.field(validator=attrs.validators.instance_of(int), default=1)
    raise AssertionError('should have raised')
except ValueError as e:
    assert "Frozen classes can't use on_setattr" in str(e)

@attrs.frozen
class Base:
    x: int = 1

try:
    @attrs.define(on_setattr=attrs.setters.validate)
    class Sub(Base):
        y: int = 2
    raise AssertionError('should have raised')
except ValueError as e:
    assert 'frozen-ness was inherited' in str(e)
print('ok')

import os, sys
sys.path.insert(0, os.path.join(os.getcwd(), 'src'))
import attrs
from attrs.exceptions import NotAnAttrsClassError

@attrs.define
class A:
    x: int = 1

assert attrs.fields(A(1)) is attrs.fields(A)
assert attrs.fields(A).x is attrs.fields_dict(A)['x']
try:
    attrs.fields_dict(A(1))
    raise AssertionError
except TypeError as e:
    assert 'must be a class' in str(e)
try:
    attrs.fields(42)
    raise AssertionError
except TypeError as e:
    assert 'class or attrs instance' in str(e)
try:
    attrs.fields(object)
    raise AssertionError
except NotAnAttrsClassError:
    pass
print('ok')
